{"file_path":"src/cli.js","content":"#!/usr/bin/env node

import { readFileSync } from 'fs'

const mode = process.argv[2]

// Validate mode
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Read input from stdin
const input = readFileSync(0, 'utf8')
const lines = input.endsWith('\n') ? input.slice(0, -1).split('\n') : input.split('\n')

// Find separator indices
const sepIndices = lines.map((l, i) => l === '%%%' ? i : -1).filter(i => i >= 0)

if (sepIndices.length !== 2) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

const mine = lines.slice(0, sepIndices[0])
const base = lines.slice(sepIndices[0] + 1, sepIndices[1])
const theirs = lines.slice(sepIndices[1] + 1)

// LCS with specific tie-breaking: advance the side with more remaining,
// preferring to advance base when tied
function computeLCS(doc1, doc2) {
  const matches = []
  let i = 0, j = 0

  while (i < doc1.length && j < doc2.length) {
    if (doc1[i] === doc2[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const remaining1 = doc1.length - i
      const remaining2 = doc2.length - j

      if (remaining2 > remaining1) {
        j++
      } else {
        i++
      }
    }
  }

  return matches
}

// Generate changes from LCS
function generateChanges(base, side, lcsMatches) {
  const changes = []
  let baseIdx = 0
  let sideIdx = 0

  for (const [baseMatch, sideMatch] of lcsMatches) {
    if (baseIdx < baseMatch || sideIdx < sideMatch) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: baseMatch,
        sideStart: sideIdx,
        sideEnd: sideMatch
      })
    }
    baseIdx = baseMatch + 1
    sideIdx = sideMatch + 1
  }

  if (baseIdx < base.length || sideIdx < side.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      sideStart: sideIdx,
      sideEnd: side.length
    })
  }

  return changes
}

// Get lines for a base range from side using LCS info
function getSideLines(baseStart, baseEnd, lcsMatches, side) {
  // Create mapping from base index to side index
  const baseToSide = new Map()
  for (const [b, s] of lcsMatches) {
    baseToSide.set(b, s)
  }

  // Find the range of side indices covering [baseStart, baseEnd)
  let minSide = side.length
  let maxSide = -1

  for (let b = baseStart; b < baseEnd; b++) {
    if (baseToSide.has(b)) {
      const s = baseToSide.get(b)
      minSide = Math.min(minSide, s)
      maxSide = Math.max(maxSide, s)
    }
  }

  // If no matches in range, find nearby matches to bracket the range
  if (maxSide === -1) {
    // Find first match after baseEnd
    for (const [b, s] of lcsMatches) {
      if (b >= baseEnd) {
        return side.slice(0, s)
      }
    }
    // No match after, so take all remaining
    return side.slice(0)
  }

  // Include all side lines from minSide to maxSide + 1
  return side.slice(minSide, maxSide + 1)
}

// Compute changes for both sides
const mineChanges = generateChanges(base, mine, computeLCS(base, mine))
const theirsChanges = generateChanges(base, theirs, computeLCS(base, theirs))

// Merge changes into regions, sorting by base position (mine first if tied)
const allChanges = []
for (const change of mineChanges) {
  allChanges.push({ ...change, side: 'mine' })
}
for (const change of theirsChanges) {
  allChanges.push({ ...change, side: 'theirs' })
}

allChanges.sort((a, b) => {
  if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
  return a.side === 'mine' ? -1 : 1
})

// Build regions
const regions = []
let i = 0

while (i < allChanges.length) {
  const firstChange = allChanges[i]
  const region = {
    baseStart: firstChange.baseStart,
    baseEnd: firstChange.baseEnd,
    changes: [firstChange]
  }

  i++

  // Absorb subsequent changes that overlap
  while (i < allChanges.length && allChanges[i].baseStart <= region.baseEnd) {
    region.changes.push(allChanges[i])
    region.baseEnd = Math.max(region.baseEnd, allChanges[i].baseEnd)
    i++
  }

  regions.push(region)
}

// Add stable regions between changes
const finalRegions = []
let lastEnd = 0

for (const region of regions) {
  if (lastEnd < region.baseStart) {
    finalRegions.push({
      baseStart: lastEnd,
      baseEnd: region.baseStart,
      changes: []
    })
  }
  finalRegions.push(region)
  lastEnd = region.baseEnd
}

if (lastEnd < base.length) {
  finalRegions.push({
    baseStart: lastEnd,
    baseEnd: base.length,
    changes: []
  })
}

// Resolve regions
const resolvedLines = []
let hasConflict = false
const regionInfo = []

const mineLCS = computeLCS(base, mine)
const theirsLCS = computeLCS(base, theirs)

for (const region of finalRegions) {
  const mineChangesInRegion = region.changes.filter(c => c.side === 'mine')
  const theirsChangesInRegion = region.changes.filter(c => c.side === 'theirs')

  if (mineChangesInRegion.length === 0 && theirsChangesInRegion.length === 0) {
    // Stable region
    const lines = base.slice(region.baseStart, region.baseEnd)
    resolvedLines.push(...lines)
    regionInfo.push({ type: 'stable', count: lines.length })
  } else if (mineChangesInRegion.length === 0) {
    // Only theirs changed
    const lines = getSideLines(region.baseStart, region.baseEnd, theirsLCS, theirs)
    resolvedLines.push(...lines)
    regionInfo.push({ type: 'theirs', count: lines.length })
  } else if (theirsChangesInRegion.length === 0) {
    // Only mine changed
    const lines = getSideLines(region.baseStart, region.baseEnd, mineLCS, mine)
    resolvedLines.push(...lines)
    regionInfo.push({ type: 'mine', count: lines.length })
  } else {
    // Both sides changed - check for conflict
    const mineLines = getSideLines(region.baseStart, region.baseEnd, mineLCS, mine)
    const theirsLines = getSideLines(region.baseStart, region.baseEnd, theirsLCS, theirs)
    const baseLines = base.slice(region.baseStart, region.baseEnd)

    const mineStr = mineLines.join('\n')
    const theirsStr = theirsLines.join('\n')
    const baseStr = baseLines.join('\n')

    if (mineStr === theirsStr) {
      // Same change on both sides
      resolvedLines.push(...mineLines)
      regionInfo.push({ type: 'both', count: mineLines.length })
    } else if (mineStr === baseStr) {
      // Only theirs actually changed
      resolvedLines.push(...theirsLines)
      regionInfo.push({ type: 'theirs', count: theirsLines.length })
    } else if (theirsStr === baseStr) {
      // Only mine actually changed
      resolvedLines.push(...mineLines)
      regionInfo.push({ type: 'mine', count: mineLines.length })
    } else {
      // Conflict
      hasConflict = true
      if (mode === 'merge') {
        resolvedLines.push('<<<<<<< mine')
        resolvedLines.push(...mineLines)
        resolvedLines.push('||||||| base')
        resolvedLines.push(...baseLines)
        resolvedLines.push('=======')
        resolvedLines.push(...theirsLines)
        resolvedLines.push('>>>>>>> theirs')
      } else if (mode === 'merge2') {
        resolvedLines.push('<<<<<<< mine')
        resolvedLines.push(...mineLines)
        resolvedLines.push('=======')
        resolvedLines.push(...theirsLines)
        resolvedLines.push('>>>>>>> theirs')
      }
      regionInfo.push({
        type: 'conflict',
        mineCount: mineLines.length,
        baseCount: baseLines.length,
        theirsCount: theirsLines.length
      })
    }
  }
}

// Output
if (mode === 'regions') {
  for (const info of regionInfo) {
    if (info.type === 'stable') {
      process.stdout.write(`stable ${info.count}\n`)
    } else if (info.type === 'mine') {
      process.stdout.write(`mine ${info.count}\n`)
    } else if (info.type === 'theirs') {
      process.stdout.write(`theirs ${info.count}\n`)
    } else if (info.type === 'both') {
      process.stdout.write(`both ${info.count}\n`)
    } else if (info.type === 'conflict') {
      process.stdout.write(`conflict mine=${info.mineCount} base=${info.baseCount} theirs=${info.theirsCount}\n`)
    }
  }
} else {
  // merge or merge2
  for (const line of resolvedLines) {
    process.stdout.write(`${line}\n`)
  }
}

process.exit(hasConflict ? 1 : 0)
"}

