{"file_path":"src/diff.js","content":"/**
 * Line diff of a base document against one side, via a longest common
 * subsequence over whole lines compared as exact strings.
 */

/**
 * The matches of a longest common subsequence of `base` and `side`, as pairs
 * of indices. Ties are broken towards the earliest matches: walking both
 * documents from the start, a match is taken whenever the two current lines
 * are equal, and otherwise the side whose remaining subsequence is at least
 * as long as the other's is advanced, preferring the base when they tie.
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // table[i][j] is the length of the LCS of base[i..] and side[j..].
  const table = new Array(n + 1)
  for (let i = 0; i <= n; i++) table[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      table[i][j] = base[i] === side[j]
        ? table[i + 1][j + 1] + 1
        : Math.max(table[i + 1][j], table[i][j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * The stretches the subsequence does not cover, each a run of base lines
 * replaced by a run of the side's lines.
 */
export function changes(base, side) {
  const result = []
  let baseAt = 0
  let sideAt = 0
  const push = (baseEnd, sideEnd) => {
    if (baseAt < baseEnd || sideAt < sideEnd) {
      result.push({ baseStart: baseAt, baseEnd, sideStart: sideAt, sideEnd })
    }
  }
  for (const [baseIndex, sideIndex] of lcsMatches(base, side)) {
    push(baseIndex, sideIndex)
    baseAt = baseIndex + 1
    sideAt = sideIndex + 1
  }
  push(base.length, side.length)
  return result
}
"}

