import { changes } from './diff.js'

/**
 * The regions of a three-way merge, in base order. A region is either
 * `stable`, `both`, `mine`, `theirs` or `conflict`, and always carries the
 * three runs of lines it was decided from.
 */
export function regionsOf(mine, base, theirs) {
  const gathered = [
    ...changes(base, mine).map(change => ({ ...change, side: 'mine' })),
    ...changes(base, theirs).map(change => ({ ...change, side: 'theirs' })),
  ].sort((a, b) =>
    a.baseStart - b.baseStart || (a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1))

  const clusters = []
  for (let i = 0; i < gathered.length;) {
    const cluster = { start: gathered[i].baseStart, end: gathered[i].baseEnd, changes: [gathered[i]] }
    i++
    while (i < gathered.length && gathered[i].baseStart <= cluster.end) {
      cluster.changes.push(gathered[i])
      cluster.end = Math.max(cluster.end, gathered[i].baseEnd)
      i++
    }
    clusters.push(cluster)
  }

  const regions = []
  let at = 0
  const stable = end => {
    if (at < end) regions.push({ kind: 'stable', lines: base.slice(at, end), mine: null, base: null, theirs: null })
  }
  for (const cluster of clusters) {
    stable(cluster.start)
    regions.push(resolve(cluster, mine, base, theirs))
    at = cluster.end
  }
  stable(base.length)
  return regions
}

/** The lines one side puts in place of a region of the base. */
function sideLines(cluster, side, document, base) {
  const own = cluster.changes.filter(change => change.side === side)
  if (own.length === 0) return base.slice(cluster.start, cluster.end)
  const baseStart = Math.min(...own.map(change => change.baseStart))
  const baseEnd = Math.max(...own.map(change => change.baseEnd))
  const start = Math.min(...own.map(change => change.sideStart)) - (baseStart - cluster.start)
  const end = Math.max(...own.map(change => change.sideEnd)) + (cluster.end - baseEnd)
  return document.slice(start, end)
}

function resolve(cluster, mine, base, theirs) {
  const mineLines = sideLines(cluster, 'mine', mine, base)
  const theirsLines = sideLines(cluster, 'theirs', theirs, base)
  const baseLines = base.slice(cluster.start, cluster.end)
  const region = { mine: mineLines, base: baseLines, theirs: theirsLines }
  if (same(mineLines, theirsLines)) return { ...region, kind: 'both', lines: mineLines }
  if (same(mineLines, baseLines)) return { ...region, kind: 'theirs', lines: theirsLines }
  if (same(theirsLines, baseLines)) return { ...region, kind: 'mine', lines: mineLines }
  return { ...region, kind: 'conflict', lines: null }
}

function same(one, other) {
  return one.length === other.length && one.every((line, index) => line === other[index])
}
"}

